<?php
declare(strict_types=1);
$f=__DIR__.'/config.php';$cfg=file_exists($f)?require $f:require __DIR__.'/config.example.php';
date_default_timezone_set($cfg['timezone']??'UTC');session_name($cfg['session_name']??'rblx08_session');
if(session_status()!==PHP_SESSION_ACTIVE)session_start(['cookie_httponly'=>true,'cookie_samesite'=>'Lax','use_strict_mode'=>true]);
function e(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function route(string $p,array $q=[]):string{$r=['Default'=>'/Default.aspx','Games'=>'/Games.aspx','Browse'=>'/Browse.aspx','Catalog'=>'/Catalog.aspx','Item'=>'/Item.aspx','User'=>'/User.aspx','Inventory'=>'/Inventory.aspx','Login'=>'/Login.aspx','Register'=>'/Register.aspx','Forum/ShowForum'=>'/Forum/ShowForum.aspx','Forum/ShowPost'=>'/Forum/ShowPost.aspx'];return($r[$p]??'/').($q?'?'.http_build_query($q):'');}
function go(string $u):never{header('Location: '.$u,true,303);exit;}
function token():string{if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(32));return $_SESSION['csrf'];}
function check_token():void{if(!hash_equals(token(),(string)($_POST['_csrf']??''))){http_response_code(419);exit('Invalid form token. Reload the page.');}}
function say(string $m,string $t='info'):void{$_SESSION['flash'][]=[$m,$t];}
function db():?PDO{static $p=false;if($p instanceof PDO)return$p;if($p===null)return null;$c=$GLOBALS['cfg']['database']??[];try{$p=new PDO(sprintf('mysql:host=%s;port=%d;dbname=%s;charset=%s',$c['host']??'127.0.0.1',(int)($c['port']??3306),$c['name']??'rblx08',$c['charset']??'utf8mb4'),$c['user']??'',$c['password']??'', [PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);return$p;}catch(PDOException $e){error_log($e->getMessage());$p=null;return null;}}
function rows(string $sql,array $a=[]):array{if(!db())return[];$s=db()->prepare($sql);$s->execute($a);return$s->fetchAll();}
function one(string $sql,array $a=[]):?array{return rows($sql,$a)[0]??null;}
function logged():?array{return $_SESSION['user']??null;}
function need_login():array{if(!logged()){say('Please sign in first.','warning');go(route('Login'));}return logged();}
function items(string $type=''):array{$sql='SELECT i.*,u.username creator_name FROM catalog_items i LEFT JOIN users u ON u.id=i.creator_id';$a=[];if(in_array($type,['hat','face','shirt','pants','gear','other'],true)){$sql.=' WHERE i.item_type=?';$a[]=$type;}return rows($sql.' ORDER BY i.id DESC LIMIT 60',$a);}
$page=trim((string)($_GET['page']??'Default'),'/');$valid=['Default','Games','Browse','Catalog','Item','User','Inventory','Login','Register','Forum/ShowForum','Forum/ShowPost'];if(!in_array($page,$valid,true))$page='Default';
$title='Home';$body='';$user=logged();
if($page==='Login'||$page==='Register'){
 $title=$page;
 if($_SERVER['REQUEST_METHOD']==='POST'){check_token();$name=trim((string)($_POST['username']??''));$pass=(string)($_POST['password']??'');
  if(($_POST['action']??'')==='logout'){$_SESSION=[];session_regenerate_id(true);say('Signed out.');go(route('Default'));}
  if($page==='Register'){$email=trim((string)($_POST['email']??''));if(!preg_match('/^[A-Za-z0-9_]{3,20}$/',$name)||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8)say('Enter a 3–20 character username, valid email and password of at least 8 characters.','warning');elseif(db()){try{$s=db()->prepare('INSERT INTO users(username,email,password_hash) VALUES(?,?,?)');$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);session_regenerate_id(true);$_SESSION['user']=['id'=>(int)db()->lastInsertId(),'username'=>$name];say('Account created!');go(route('Default'));}catch(PDOException $e){say('Username or email may already exist.','warning');}}else say('Configure config.php and import database/schema.sql first.','warning');}
  elseif(db()&&($u=one('SELECT id,username,password_hash FROM users WHERE username=? OR email=? LIMIT 1',[$name,$name]))&&password_verify($pass,$u['password_hash'])){session_regenerate_id(true);$_SESSION['user']=['id'=>(int)$u['id'],'username'=>$u['username']];db()->prepare('UPDATE users SET last_login_at=NOW() WHERE id=?')->execute([$u['id']]);say('Welcome back!');go(route('Default'));}else say('Login failed. Check your details.','warning');
 }
 if($user)$body='<section class="panel"><h1>Already signed in</h1></section>';else{$body='<section class="auth panel"><h1>'.($page==='Register'?'Create an account':'Welcome back').'</h1><form method="post"><input type="hidden" name="_csrf" value="'.e(token()).'">'.($page==='Register'?'<label>Username<input name="username" minlength="3" maxlength="20" pattern="[A-Za-z0-9_]+" required></label><label>Email<input type="email" name="email" required></label>':'<label>Username or email<input name="username" required></label>').'<label>Password<input type="password" name="password" minlength="'.($page==='Register'?'8':'1').'" required></label><button>'.($page==='Register'?'Create account':'Login').'</button></form><p>'.($page==='Register'?'<a href="'.e(route('Login')).'">Login</a>':'<a href="'.e(route('Register')).'">Create account</a>').'</p></section>';}
}
elseif($page==='Item'){$title='Catalog Item';$i=one('SELECT * FROM catalog_items WHERE id=?',[(int)($_GET['id']??0)]);$body=$i?'<section class="panel"><h1>'.e($i['name']).'</h1><p>'.e($i['description']??'').'</p><b>'.number_format((int)$i['price']).' tickets</b></section>':'<section class="panel"><h1>Item not found</h1></section>';}
elseif($page==='User'){$title='Player Profile';$u=one('SELECT id,username,description,created_at FROM users WHERE id=?',[(int)($_GET['ID']??$_GET['id']??0)]);$body=$u?'<section class="panel"><h1>'.e($u['username']).'</h1><p>'.nl2br(e($u['description']??'')).'</p><h2>Inventory</h2>':'<section class="panel"><h1>User not found</h1>';if($u){foreach(rows('SELECT i.* FROM inventory v JOIN catalog_items i ON i.id=v.item_id WHERE v.user_id=?',[$u['id']]) as $i)$body.='<p><a href="'.e(route('Item',['id'=>$i['id']])).'">'.e($i['name']).'</a></p>';}$body.='</section>';}
elseif($page==='Inventory'){$title='My Inventory';$u=need_login();$body='<section class="panel"><h1>My Inventory</h1>';foreach(rows('SELECT i.* FROM inventory v JOIN catalog_items i ON i.id=v.item_id WHERE v.user_id=?',[$u['id']]) as $i)$body.='<p><a href="'.e(route('Item',['id'=>$i['id']])).'">'.e($i['name']).'</a></p>';$body.='</section>';}
elseif($page==='Forum/ShowForum'){$title='Forum';if($_SERVER['REQUEST_METHOD']==='POST'){$u=need_login();check_token();$s=trim((string)($_POST['title']??''));$b=trim((string)($_POST['body']??''));if($s!==''&&$b!==''&&db()){db()->prepare('INSERT INTO forum_topics(user_id,title,body) VALUES(?,?,?)')->execute([$u['id'],substr($s,0,160),$b]);say('Topic posted.');go(route('Forum/ShowForum'));}}$body='<section class="panel"><h1>Community Forum</h1>';if($user)$body.='<form method="post"><input type="hidden" name="_csrf" value="'.e(token()).'"><label>Title<input name="title" required maxlength="160"></label><label>Message<textarea name="body" required></textarea></label><button>Post topic</button></form>';foreach(rows('SELECT t.*,u.username FROM forum_topics t JOIN users u ON u.id=t.user_id ORDER BY t.id DESC LIMIT 60') as $t)$body.='<p><a href="'.e(route('Forum/ShowPost',['id'=>$t['id']])).'">'.e($t['title']).'</a> — '.e($t['username']).'</p>';$body.='</section>';}
elseif($page==='Forum/ShowPost'){$title='Forum Topic';$t=one('SELECT t.*,u.username FROM forum_topics t JOIN users u ON u.id=t.user_id WHERE t.id=?',[(int)($_GET['id']??0)]);$body='<section class="panel">';if($t){$body.='<h1>'.e($t['title']).'</h1><p>'.nl2br(e($t['body'])).'</p>';foreach(rows('SELECT r.*,u.username FROM forum_replies r JOIN users u ON u.id=r.user_id WHERE topic_id=? ORDER BY r.id',[$t['id']]) as $r)$body.='<article><b>'.e($r['username']).'</b><p>'.nl2br(e($r['body'])).'</p></article>';if($user&&$_SERVER['REQUEST_METHOD']==='POST'){check_token();$b=trim((string)($_POST['body']??''));if($b!==''){db()->prepare('INSERT INTO forum_replies(topic_id,user_id,body) VALUES(?,?,?)')->execute([$t['id'],$user['id'],$b]);db()->prepare('UPDATE forum_topics SET replies_count=replies_count+1 WHERE id=?')->execute([$t['id']]);go(route('Forum/ShowPost',['id'=>$t['id']]));}}if($user)$body.='<form method="post"><input type="hidden" name="_csrf" value="'.e(token()).'"><textarea name="body" required></textarea><button>Reply</button></form>'; }else $body.='<h1>Topic not found</h1>';$body.='</section>';}
else{
 $title=match($page){'Games'=>'Games','Browse'=>'Browse','Catalog'=>'Catalog',default=>'Home'};
 $body='<div class="page-heading"><h1>'.e($title).'</h1><p>Build, battle, chat, or just hang out.</p></div>';
 if($page==='Games'||$page==='Default'){$body.='<section class="content-box"><h2 class="section-title">Featured Games</h2><div class="cards">';foreach(rows('SELECT g.*,u.username FROM games g LEFT JOIN users u ON u.id=g.creator_id ORDER BY g.id DESC LIMIT 30') as $g)$body.='<article class="card"><div class="thumb">PLAY</div><h3>'.e($g['name']).'</h3><p>'.e($g['description']??'').'</p></article>';$body.='</div></section>';}
 if(in_array($page,['Catalog','Browse','Default'],true)){$body.='<section class="content-box"><h2 class="section-title">Catalog</h2><div class="cards">';foreach(items((string)($_GET['type']??'')) as $i)$body.='<a class="card" href="'.e(route('Item',['id'=>$i['id']])).'"><div class="thumb">'.e(strtoupper(substr($i['item_type'],0,1))).'</div><h3>'.e($i['name']).'</h3><p>'.number_format((int)$i['price']).' tickets</p></a>';$body.='</div></section>';}
}
$flashes=$_SESSION['flash']??[];unset($_SESSION['flash']);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?> - <?=e($cfg['app_name'])?></title><link rel="stylesheet" href="/assets/css/site.css"></head><body><div id="Container"><div id="Header"><div id="Banner"><a class="logo" href="<?=e(route('Default'))?>">ROBLOX</a><div class="banner-message">A FREE Virtual World-Building Game<br><small>Build, battle, chat, or just hang out.</small></div><div class="account"><?php if($user): ?>Welcome, <?=e($user['username'])?> · <a href="<?=e(route('User',['ID'=>$user['id']]))?>">My Profile</a> · <a href="<?=e(route('Inventory'))?>">Inventory</a><form class="inline" method="post" action="<?=e(route('Login'))?>"><input type="hidden" name="_csrf" value="<?=e(token())?>"><input type="hidden" name="action" value="logout"><button class="textbutton">Logout</button></form><?php else: ?><a href="<?=e(route('Login'))?>">Login</a> | <a href="<?=e(route('Register'))?>">Sign Up</a><?php endif; ?></div></div><div class="Navigation"><a class="MenuItem" href="<?=e(route('Default'))?>">Home</a><span class="Separator">|</span><a class="MenuItem" href="<?=e(route('User'))?>">My ROBLOX</a><span class="Separator">|</span><a class="MenuItem" href="<?=e(route('Games'))?>">Games</a><span class="Separator">|</span><a class="MenuItem" href="<?=e(route('Catalog'))?>">Catalog</a><span class="Separator">|</span><a class="MenuItem" href="<?=e(route('Browse'))?>">Browse</a><span class="Separator">|</span><a class="MenuItem" href="<?=e(route('Forum/ShowForum'))?>">Forum</a></div></div><main id="MainContent"><?php foreach($flashes as $f): ?><div class="notice"><?=e($f[0])?></div><?php endforeach; ?><?=$body?></main><div id="Footer">ROBLOX 2008 Revival · Independent fan project, not affiliated with Roblox Corporation.</div></div></body></html>
